"rb_feed_when":{"message0":"όταν υπάρχει κάτι νέο στη ροή %1","tooltip":"Εκτελεί τα μπλοκ από κάτω για κάθε νέο στοιχείο μιας ροής ειδήσεων (έλεγχος κάθε 15 λεπτά). Αφήστε το κενό για τις δικές σας ροές. Το «ό,τι έφτασε» δίνει feed, title, link, date, summary και text."},
"rb_file_choose":{"message0":"κείμενο αρχείου που διαλέγω","tooltip":"Παγώνει την εκτέλεση για να διαλέξετε PDF, .docx του Word ή αρχείο κειμένου. Επιστρέφει το κείμενο του αρχείου."},
"rb_file_save":{"message0":"αποθήκευσε %1 ως αρχείο %2 . %3","tooltip":"Προσφέρει το κείμενο για λήψη. Ο περιηγητής σας ζητά επιβεβαίωση."},
"rb_finish_with":{"message0":"τελείωσε με %1"},
